#[derive(Clone,Copy,Debug)]struct Recipe{wire:usize,a:usize,b:usize,kind:K,guard:u32,producer:usize}
struct PeakRegion{lo:usize,candidates:Vec<Recipe>,touches:HashSet<usize>,writes:HashSet<usize>}
fn peak_audit(ops:&[Op])->serde_json::Value{
 let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);let cap=nq-1;let mut alg=Algebra{inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq,nb,&mut alg);let pinned:HashSet<_>=ops.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=no).map(|o|o.q_target.0 as usize).collect();let mut active:Vec<bool>=(0..nq).map(|j|pinned.contains(&j)).collect();let mut live=pinned.len();let mut recipes=vec![None;nq];let(mut base,mut stack)=(1,vec![]);let mut pending:Option<PeakRegion>=None;let mut rows=vec![];let mut ccx_loans=0usize;let mut free_loans=0usize;let mut failed=0usize;let mut original_peak=live;
 for(i,o)in ops.iter().enumerate(){
  if o.kind==K::PushCondition{stack.push(base);base=alg.inner.and(base,c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{base=stack.pop().unwrap();continue;}
  let g=if o.c_condition.0==no{base}else{alg.inner.and(base,c[o.c_condition.0 as usize])};let(t,a,b,ct)=(o.q_target.0 as usize,o.q_control1.0 as usize,o.q_control2.0 as usize,o.c_target.0 as usize);let mut used:Vec<_>=[o.q_control2.0,o.q_control1.0,o.q_target.0].into_iter().filter(|&j|j!=no).map(|j|j as usize).collect();used.sort_unstable();used.dedup();
  let new_count=used.iter().filter(|&&j|!active[j]).count();let need=live+new_count;original_peak=original_peak.max(need);
  if need>cap&&pending.is_none(){assert_eq!(need,cap+1);let mut candidates=vec![];for wire in 0..nq{if pinned.contains(&wire)||!active[wire]||q[wire]==0{continue;}let Some(recipe)=recipes[wire]else{continue;};let r:Recipe=recipe;let actual=match r.kind{K::X=>r.guard,K::CX=>alg.inner.and(r.guard,q[r.a]),K::CCX=>{let ab=alg.inner.and(q[r.a],q[r.b]);alg.inner.and(r.guard,ab)},_=>unreachable!()};if actual==q[wire]{candidates.push(r);}}
   pending=Some(PeakRegion{lo:i,candidates,touches:HashSet::new(),writes:HashSet::new()});
  }
  for &j in &used{if !active[j]{active[j]=true;live+=1;}}
  let mut affected=vec![];if matches!(o.kind,K::X|K::CX|K::CCX|K::Swap|K::R|K::Hmr){affected.push(t);if o.kind==K::Swap{affected.push(a);}}
  if let Some(region)=&mut pending{region.touches.extend(used.iter().copied());region.writes.extend(affected.iter().copied());}
  let recipe=if matches!(o.kind,K::X|K::CX|K::CCX)&&q[t]==0{Some(Recipe{wire:t,a,b,kind:o.kind,guard:g,producer:i})}else{None};for &j in &affected{recipes[j]=None;}
  match o.kind{K::X=>q[t]=alg.inner.xor(q[t],g),K::CX=>{let v=alg.inner.and(q[a],g);q[t]=alg.inner.xor(q[t],v);},K::CCX=>{let v=alg.inner.and(q[a],q[b]);let v=alg.inner.and(g,v);q[t]=alg.inner.xor(q[t],v);},K::Swap=>{let v=alg.inner.xor(q[a],q[t]);let v=alg.inner.and(g,v);q[a]=alg.inner.xor(q[a],v);q[t]=alg.inner.xor(q[t],v);},K::R|K::Hmr=>{q[t]=alg.inner.and(q[t],g^1);if o.kind==K::Hmr{let r=alg.inner.atom();c[ct]=alg.inner.ite(g,r,c[ct]);}},K::BitInvert=>c[ct]=alg.inner.xor(c[ct],g),K::BitStore0=>c[ct]=alg.inner.and(c[ct],g^1),K::BitStore1=>c[ct]=alg.inner.or(c[ct],g),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  if let Some(recipe)=recipe{recipes[t]=Some(recipe);}
  for &j in &used{if !pinned.contains(&j)&&q[j]==0{assert!(active[j]);active[j]=false;live-=1;}}
  if live<=cap{if let Some(region)=pending.take(){let mut good:Vec<_>=region.candidates.iter().copied().filter(|r|!region.touches.contains(&r.wire)&&(r.kind==K::X||!region.writes.contains(&r.a))&&(r.kind!=K::CCX||!region.writes.contains(&r.b))).collect();good.sort_by_key(|r|(u32::from(r.kind==K::CCX),u32::from(r.kind==K::CX),r.wire));let count=good.len();if let Some(r)=good.first(){if r.kind==K::CCX{ccx_loans+=1;}else{free_loans+=1;}rows.push(serde_json::json!({"lo":region.lo,"hi":i,"status":"EXACT_RECIPE_AND_IDLE_REGION_PROVED","candidates":count,"wire":r.wire,"a":r.a,"b":r.b,"kind":r.kind as u32,"producer":r.producer,"captured_guard_expression":r.guard,"extra_toffoli_records_upper_bound":if r.kind==K::CCX{2}else{0}}));}else{failed+=1;rows.push(serde_json::json!({"lo":region.lo,"hi":i,"status":"NO_CURRENT_SIMPLE_RECIPE_SURVIVES_REGION","initial_recipe_candidates":region.candidates.len(),"touched_quantum_wires":region.touches.len(),"written_quantum_wires":region.writes.len()}));}}}
  if i%1000000==0{eprintln!("PEAK_REMAT op={i} regions={} free_loans={free_loans} ccx_loans={ccx_loans} failed={failed} nodes={}",rows.len(),alg.inner.nodes.len());}
 }
 assert!(stack.is_empty());let incomplete=pending.is_some();serde_json::json!({"status":"READ_ONLY_PEAK_REMATERIALIZATION_PLAN_NOT_AN_EMITTED_CIRCUIT_OR_SCORE","original_qubits":nq,"target_cap":cap,"conservative_original_lifetime_peak":original_peak,"regions":rows,"zero_toffoli_recipe_regions":free_loans,"two_toffoli_recipe_regions":ccx_loans,"unproved_regions":failed,"unfinished_final_region":incomplete,"all_regions_covered":failed==0&&!incomplete,"extra_executed_toffoli_per_shot_upper_bound":2*ccx_loans,"semantic_nodes":alg.inner.nodes.len(),"input_records_sha3":hash(ops),"scope":"Each selected helper is a proved X/CX/CCX of original historical classical guard and CURRENT controls; helper untouched and controls unwritten through overflow region. Uncompute before region and restore after a physical slot frees. Historical guard must be captured at original producer, both inserted gates outside original scope stack via exact guard flattening. No inserted RNG. This is a source-bound plan, NOT achieved Q/T; actual allocator/guard emitter/native full phase/RNG qualification and final pipeline required."})
}
#[cfg(test)]mod peak_remat_tests{use super::*;
 fn fixture(kind:K)->Vec<Op>{let n=u64::MAX;let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(0);o.q_target=QubitId(q);ops.push(o);}let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=quantum_ecc::circuit::RegisterId(1);o.c_target=BitId(0);ops.push(o);ops.extend([make(kind,if kind==K::CCX{1}else{n},0,4,n,0),make(K::CX,n,1,5,n,n),make(K::R,n,n,5,n,n),make(K::CX,n,4,2,n,n),make(K::R,n,n,4,n,n)]);ops}
 #[test]fn peak_island_has_exact_idle_clifford_or_toffoli_recipe(){for kind in[K::CX,K::CCX]{let s=peak_audit(&fixture(kind));assert_eq!(s["target_cap"],5);assert_eq!(s["conservative_original_lifetime_peak"],6);assert_eq!(s["all_regions_covered"],true);assert_eq!(s["extra_executed_toffoli_per_shot_upper_bound"],if kind==K::CX{0}else{2});}}
 #[test]fn uncompute_restore_preserves_full_phase_values_rng_and_captured_old_classical_guard(){use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;struct W{word:u64,at:usize}impl XofReader for W{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.word.rotate_left(self.at as u32).to_le_bytes());self.at+=1;}}let n=u64::MAX;for kind in[K::CX,K::CCX]{let mut ops=fixture(kind);ops.insert(7,make(K::BitInvert,n,n,n,0,n));let plan=peak_audit(&ops);assert_eq!(plan["all_regions_covered"],true);let r=&plan["regions"][0];let(lo,hi)=(r["lo"].as_u64().unwrap()as usize,r["hi"].as_u64().unwrap()as usize);let producer=r["producer"].as_u64().unwrap()as usize;let mut out=vec![];let mut inserted=ops[producer];inserted.c_condition=BitId(1);for(i,&o)in ops.iter().enumerate(){if i==producer{out.push(make(K::BitStore0,n,n,n,1,n));out.push(make(K::BitStore1,n,n,n,1,0));}if i==lo{out.push(inserted);}out.push(o);if i==hi{out.push(inserted);}}for word in[0,u64::MAX,0xa55a_dd33_ff00_1701]{let(mut ra,mut rb)=(W{word,at:0},W{word,at:0});let(mut a,mut b)=(Simulator::new(6,2,&mut ra),Simulator::new(6,2,&mut rb));for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}a.bits[0]|=((lane>>4&1)as u64)<<lane;}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);let guard=a.bits[0];a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits[0],b.bits[0]);assert_eq!(a.phase,b.phase);assert_eq!(b.stats.toffoli_gates-a.stats.toffoli_gates,if kind==K::CCX{2*guard.count_ones()as u64}else{0});drop((a,b));assert_eq!(ra.at,rb.at);}}}
}
